  { pl: 'brahmavihāra', km: 'ព្រហ្មវិហារ', en: 'divine abiding', def: 'ធម៌ស្នាក់នៅ ដ៏ប្រសើរ ៤ គឺ មេត្តា ករុណា មុទិតា ឧបេក្ខា — ដូចព្រហ្ម ដែលស្នាក់នៅដោយចិត្តស្មើ — ជាបដិបទា នាំទៅរកសុខ និងបញ្ញា។' },
  { pl: 'citta', km: 'ចិត្ត', en: 'mind, consciousness', def: 'ចិត្ត — អ្នកដឹង អ្នកគិត អ្នកត្រេកអរ — ក្នុងអភិធម្ម មាន ៨៩ ឬ ១២១ ប្រភេទ — ជាមជ្ឈដ្ឋាន នៃការហ្វឹកហាត់ ក្នុងព្រះពុទ្ធសាសនា។' },
  { pl: 'dhamma', km: 'ធម៌', en: 'teaching, truth, phenomena', def: 'ពាក្យដែលមានន័យច្រើន — ១. គម្ពីរព្រះត្រៃបិដក ២. ការពិត និង ៣. អ្វីៗ ដែលកើត ហើយរលត់ — មានទាំងអស់ ក្នុងព្រះធម៌របស់ព្រះសម្មាសម្ពុទ្ធ។' },
  { pl: 'dhammacakka', km: 'ធម្មចក្រ', en: 'wheel of the Dhamma', def: 'កង់ធម៌ — ព្រះធម្មទេសនាទីមួយ របស់ព្រះពុទ្ធ ប្រែចិត្តពួកបញ្ចវគ្គិយ — ឈ្មោះថា ធម្មចក្កប្បវត្តនសូត្រ ប្រព្រឹត្តទៅ ដូចកង់ ដែលបង្វិល បន្តវេន។' },
  { pl: 'dhammavicaya', km: 'ធម្មវិចយៈ', en: 'investigation of Dhamma', def: 'ការពិនិត្យធម៌ ដោយបញ្ញា — ជាពោជ្ឈង្គ មួយ ក្នុងពោជ្ឈង្គ ៧ — ពិនិត្យកាយ វេទនា ចិត្ត ធម៌ ឲ្យឃើញសច្ចៈ — ផ្ទុយពីវិចិកិច្ឆា។' },
  { pl: 'dosa', km: 'ទោសៈ', en: 'hatred, aversion', def: 'សេចក្តីខឹង ក្រោធ បៀតបៀន — ជាមូលបាប មួយ ក្នុងមូលបាប ៣ — ផ្ទុយពី អទោសៈ (មេត្តា) — អ្នកមានទោសៈ ចិត្តឆេះ រលាក ដូចភ្លើង។' },
  { pl: 'ekaggatā', km: 'ឯកគ្គតា', en: 'one-pointedness', def: 'ចិត្តតម្កល់មួយ — ស្ថិតលើអារម្មណ៍តែមួយ ឥតញាប់ញ័រ — ជាអង្គ នៃឈាន និងជាសម្មាសមាធិ — ជាគ្រឹះនាំឲ្យឃើញច្បាស់។' },
