  { pl: 'gāthā', km: 'គាថា', en: 'verse, stanza', def: 'ពាក្យរៀបរៀង ជាខន្ធ មានចង្វាក់ — ដូចជាក្នុងធម្មបទ — ងាយចាំ សម្រាប់សូត្រ និងរំពឹង — ជាភាសាបាលី ជាទូទៅ។' },
  { pl: 'hiri · ottappa', km: 'ហិរិ ឱត្តប្បៈ', en: 'shame & fear of wrong', def: 'ធម៌ទាំងពីរ ដែលថែរក្សាលោក — ហិរិ ខ្មាសខ្លួនឯង ឱត្តប្បៈ ខ្លាចបាប ដោយគោរពអ្នកដទៃ — ជាអ្នកបញ្ឈប់ កុំឲ្យធ្វើអាក្រក់ — ក្នុងអភិធម្ម រាប់ក្នុងសោភនចេតសិក។' },
  { pl: 'indriya', km: 'ឥន្ទ្រិយ', en: 'faculty', def: 'មន្ទីរដែលមានអានុភាព ៥ — សទ្ធា វិរិយៈ សតិ សមាធិ បញ្ញា — ដូចជា ឥន្ទ្រិយ ៥ ដែលត្រូវចម្រើន ឲ្យស្មើ ទើបបដិបត្តិសម្រេច។' },
  { pl: 'kāma', km: 'កាម', en: 'sensual desire, sense pleasures', def: 'សេចក្តីប្រាថ្នា ក្នុងអារម្មណ៍ទាំង ៥ — រូប សំឡេង ក្លិន រស សម្ផស្ស — ជាអ្នកជាប់ចិត្ត ឲ្យវិលក្នុងសង្សារ — ព្រះពុទ្ធ ទ្រង់ប្រៀបដូចឆ្អឹង ដែលមានឈាម ឲ្យឆ្កែលិទ្ធ មិនឆ្អែត។' },
