  { pl: 'saṅkhāra', km: 'សង្ខារ', en: 'formations, activities', def: 'អ្វីៗ ដែលលោកសន្សំ បង្កើតឡើង — មានវត្ថុ និងចិត្ត — ជាខន្ធ ទី ៤ — សង្ខារ តែងរលត់ — វយធម្មា សង្ខារា។' },
  { pl: 'saṅkappa', km: 'សង្កប្បៈ', en: 'intention, resolve', def: 'សេចក្តីត្រិះរិះ គិតសម្រេច — មាន ៣៖ នេក្ខម្មសង្កប្បៈ អព្យាបាទសង្កប្បៈ អវិហិង្សាសង្កប្បៈ — ជាសម្មាសង្កប្បៈ អង្គទី ២ នៃមគ្គ ៨។' },
  { pl: 'sati', km: 'សតិ', en: 'mindfulness', def: 'ការចាំ — ការរឭក អារម្មណ៍ មិនឲ្យភ្លាត់ — ជាពោជ្ឈង្គ ឥន្ទ្រិយ និងសម្មាសតិ — ដូចជា អ្នកថែសត្វ រក្សាគោ ឲ្យនៅក្នុងហ្វូង។' },
